async function notify(helpers, title, message, click) {
  const topic = ($env.NTFY_TOPIC || '').trim();
  if (!topic) return;
  try {
    await helpers.httpRequest({
      method: 'POST', url: 'https://ntfy.sh/' + encodeURIComponent(topic), body: message,
